
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_c_lypr_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_c_lypr", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-5.970879769054441e-02, -5.950869577851423e-02, -5.921158524771896e-02, -5.876413899254317e-02, -5.807621138279227e-02, -5.698603360713606e-02, -5.517991991099735e-02, -5.198932466060469e-02, -4.585561413644993e-02, -3.338618951771113e-02, -1.623896172562337e-02, -2.591680002719971e-02, -2.648548395725769e-02, -2.163012081650167e-02, -1.262960370299632e-02, -5.926176997042637e-03, -2.136859104689934e-03, -2.307499563878639e-05, -1.751291893314887e-31, -0.000000000000000e+00]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


